class MockAIProvider:
    """
    Mock AI Provider for Task 1: Knowledge Brain.
    
    Provides deterministic, offline responses for local testing without requiring
    an external Claude API key. Transparently labels all responses as mock data.
    """
    def __init__(self, provider_name: str = "mock"):
        self.provider_name = provider_name

    def query(self, question: str) -> QueryResponse:
        normalized_q = question.lower().strip()

        # Check domain knowledge matching
        best_match = None
        max_matches = 0

        for item in DOMAIN_KNOWLEDGE:
            match_count = sum(1 for kw in item["keywords"] if kw in normalized_q)
            if match_count > max_matches:
                max_matches = match_count
                best_match = item

        if best_match and max_matches > 0:
            return QueryResponse(
                query=question,
                answer=f"[MOCK PROVIDER] {best_match['answer']}",
                answered=True,
                confidence=best_match["confidence"],
                provider=self.provider_name,
                is_mock=True,
                sources=[best_match["source"]],
                disclaimer=MOCK_DISCLAIMER
            )

        # Fallback when the question cannot be answered from the knowledge base
        return QueryResponse(
            query=question,
            answer=(
                "[MOCK PROVIDER] I cannot answer this question based on the currently available "
                "knowledge base. Please consult the system documentation or escalate to a human consultant."
            ),
            answered=False,
            confidence=0.0,
            provider=self.provider_name,
            is_mock=True,
            sources=[],
            disclaimer=MOCK_DISCLAIMER
        )


def get_ai_provider(provider_type: str | None = None):
    """
    Factory to return the active AI / retrieval provider.
    Defaults to MockAIProvider when AI_PROVIDER=mock or unspecified.
    Returns LocalRetrievalService when provider_type or AI_PROVIDER is 'local_retrieval'.
    """
    chosen = (provider_type or os.getenv("AI_PROVIDER", "mock")).lower().strip()
    if chosen == "local_retrieval":
        from app.services.retrieval import LocalRetrievalService
        return LocalRetrievalService()
    return MockAIProvider(provider_name="mock")

